@section('scripts')
<script>
document.addEventListener('DOMContentLoaded',loadVpPendingData);function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));}async function loadVpPendingData(){const tb=document.getElementById('vp-pending-table-body');try{const r=await fetch("{{ route('overtime.vp.pending') }}",{headers:{'Accept':'application/json'}});const d=await r.json();const rows=d.data||[];document.getElementById('stat-pending-count').textContent=rows.length;document.getElementById('badge-total-pending').textContent=`${rows.length} Tiket`;if(!rows.length){tb.innerHTML='<tr><td colspan="7"><div class="inti-empty"><span class="material-symbols-outlined inti-empty-icon">task_alt</span><div class="inti-empty-title">Tidak ada antrean approval</div><div class="inti-empty-text">Semua pengajuan pada cakupan divisi sudah diproses.</div></div></td></tr>';return;}tb.innerHTML=rows.map(x=>`<tr><td><strong>${esc(x.ticket_number)}</strong></td><td><strong>${esc(x.user?.name||'Karyawan')}</strong><div style="font-size:11px;color:#43474d">${esc(x.user?.employee?.nipeg||x.user?.email||'')}</div></td><td>${esc(x.overtime_date)}<div style="font-size:11px;color:#43474d">${esc(x.start_time)} – ${esc(x.end_time)} WIB</div></td><td><strong>${esc(x.estimated_hours)} Jam</strong></td><td>${esc(x.reason)}</td><td><span class="inti-badge inti-badge-warning">PENDING VP</span></td><td><div style="display:flex;gap:.4rem;white-space:nowrap"><button class="inti-btn inti-btn-secondary" type="button" onclick="decision('${esc(x.id)}','APPROVE')">Setujui</button><button class="inti-btn inti-btn-danger" type="button" onclick="rejectItem('${esc(x.id)}')">Tolak</button></div></td></tr>`).join('');}catch(e){tb.innerHTML='<tr><td colspan="7"><div class="inti-empty"><div class="inti-empty-title">Antrean gagal dimuat</div><div class="inti-empty-text">Silakan refresh halaman.</div></div></td></tr>';}}
async function decision(id,action,notes=null){if(action==='APPROVE'&&!confirm('Setujui pengajuan lembur ini?'))return;try{const r=await fetch(`/overtime/vp/approve/${id}`,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({action,notes})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||'Keputusan gagal diproses.');alert(d.message||'Keputusan berhasil diproses.');loadVpPendingData();}catch(e){alert(e.message);}}function rejectItem(id){const notes=prompt('Alasan penolakan (opsional):','');if(notes===null)return;decision(id,'REJECT',notes.trim()||null);}
</script>
